        half = n // 2
        return list(range(1, half + 1)) + list(range(half + 2, half * 2 + 2))
    else:
        half = n // 2
        return list(range(1, half + 1)) + [half * 2 + 2] + list(range(half + 3, half * 2 + 3))

def main():
    import sys
    input = sys.stdin.read
